fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    // Problem states n > 0, but keep this safe in case of misuse.
    if n <= 1 {
        return a.clone();
    }

    let mut result = a.clone();
    result.swap(0, n - 1);
    result
}

fn main() {
    // Simple sanity checks
    let a = vec![1, 2, 3, 4];
    let b = swap_first_and_last(&a);
    assert_eq!(b, vec![4, 2, 3, 1]);

    let a1 = vec![42];
    let b1 = swap_first_and_last(&a1);
    assert_eq!(b1, vec![42]);
}